"""Unit tests verifying camera/cropped image compatibility with FastAPI /api/analyze."""
from __future__ import annotations

import io
from pathlib import Path

from fastapi.testclient import TestClient
from PIL import Image

try:
    from Skinora.backend.app.main import app
except ImportError:
    from backend.app.main import app

client = TestClient(app)


def test_cropped_square_image_accepted_by_api():
    """Verify that a 1:1 square cropped image generated by client cropper is accepted."""
    # Simulate a 512x512 cropped JPEG image from ImageCropperModal
    cropped_img = Image.new("RGB", (512, 512), color=(220, 190, 170))
    buf = io.BytesIO()
    cropped_img.save(buf, format="JPEG", quality=95)
    buf.seek(0)

    data = {
        "skin_type": "Combination",
        "age_range": "26–35",
        "concerns": '["Acne & blemishes", "Uneven texture"]',
        "sensitivity": "Sometimes",
        "severity": 3,
    }
    files = {"photo": ("cropped_face.jpg", buf.getvalue(), "image/jpeg")}

    resp = client.post("/api/analyze", data=data, files=files)
    assert resp.status_code == 200, f"Failed with {resp.status_code}: {resp.text}"

    body = resp.json()
    assert body["photo_quality"]["uploaded"] is True
    assert "acne_prediction" in body
    assert body["acne_prediction"]["available"] is True
    assert body["acne_prediction"]["class"] in ["mild", "moderate", "severe", "very_severe"]
    assert "class_probabilities" in body["acne_prediction"]


def test_camera_capture_filename_and_aspect_ratio_accepted():
    """Verify that camera capture output (4:3 aspect ratio, camera_capture_*.jpg) is accepted."""
    camera_img = Image.new("RGB", (1280, 960), color=(215, 185, 165))
    buf = io.BytesIO()
    camera_img.save(buf, format="JPEG", quality=95)
    buf.seek(0)

    data = {
        "skin_type": "Oily",
        "age_range": "18–25",
        "concerns": '["Acne & blemishes"]',
        "sensitivity": "Rarely",
        "severity": 2,
    }
    files = {"photo": ("camera_capture_1730550000000.jpg", buf.getvalue(), "image/jpeg")}

    resp = client.post("/api/analyze", data=data, files=files)
    assert resp.status_code == 200

    body = resp.json()
    assert body["photo_quality"]["uploaded"] is True
    assert body["acne_prediction"]["available"] is True

